def apply(inputs, premises):
    component = inputs['component_id']
    view = inputs['view']
    public = inputs['public_case']
    kernel = inputs['kernel']
    facts = []
    negatives = []
    witnesses = []
    reasons = []
    complete = True
    if type(view) is not dict or view.get('extraction_status') != 'complete':
        return part([], [], [], False, [component + '_unread_or_ambiguous'])
    if not support(witnesses, view, public, False):
        complete = False
        add(reasons, component + '_complete_view_requires_current_witness')
    records = view.get('givens')
    boundaries = view.get('boundary_statements')
    if type(records) is not list or type(boundaries) is not list:
        return part(facts, negatives, witnesses, False, reasons + ['explicit_legal_channel_unread'])
    seen = set()
    for record in records:
        evidence = checked(record, public, True)
        name = record.get('predicate')
        args = record.get('arguments')
        polarity = record.get('polarity')
        basis = record.get('basis_text')
        argument_evidence = record.get('argument_evidence')
        if evidence is None or not valid_given(name, args) or polarity not in ('positive','negative') or type(basis) is not str or type(argument_evidence) is not list:
            complete = False
            continue
        quote = ' '.join([row['quote'].lower() for row in evidence])
        if basis.lower() not in quote:
            complete = False
            add(reasons, 'exact_legal_basis_not_witnessed')
            continue
        normalized = basis.lower().replace('section','').replace('§','').replace(' ','')
        marker = ''
        if name in ('s151_b','s151_b_applies'):
            marker = '151(b)'
        elif name == 's151_c_applies':
            marker = '151(c)'
        elif name == 's152_c_1':
            marker = '152(c)(1)'
        elif name == 's63_f_1_A':
            marker = '63(f)(1)(a)'
        elif name == 's63_f_1_B':
            marker = '63(f)(1)(b)'
        if marker not in normalized:
            complete = False
            add(reasons, 'general_statute_statement_not_exact_given')
            continue
        indexes = set()
        argument_ok = True
        for item in argument_evidence:
            if type(item) is not dict or type(item.get('argument_index')) is not int or type(item.get('text')) is not str or item.get('text').lower() not in quote:
                argument_ok = False
                break
            indexes.add(item.get('argument_index'))
        if not argument_ok or indexes != set(range(len(args))):
            complete = False
            add(reasons, 'legal_argument_roles_not_fully_witnessed')
            continue
        if is_target_given(kernel, name):
            complete = False
            add(reasons, 'target_legal_query_cannot_be_reasserted_as_fact')
            continue
        key = (name, tuple(args), polarity)
        if key in seen:
            continue
        seen.add(key)
        for row in evidence:
            add(witnesses, row)
        item = {'predicate': name, 'arguments': list(args)}
        add(negatives if polarity == 'negative' else facts, item)
    for record in boundaries:
        evidence = checked(record, public, True)
        if evidence is None or record.get('kind') not in ('section151_general','section151_d','section151_other','section63_f_general'):
            complete = False
            continue
        for row in evidence:
            add(witnesses, row)
    if not complete:
        add(reasons, component + '_one_or_more_records_unread_or_invalid')
    return part(facts, negatives, witnesses, complete, reasons)

def apply(inputs, premises):
    component = inputs['component_id']
    view = inputs['view']
    public = inputs['public_case']
    kernel = inputs['kernel']
    facts = []
    negatives = []
    witnesses = []
    reasons = []
    complete = True
    if type(view) is not dict or view.get('extraction_status') != 'complete':
        return part([], [], [], False, [component + '_unread_or_ambiguous'])
    if not support(witnesses, view, public, False):
        complete = False
        add(reasons, component + '_complete_view_requires_current_witness')
    payments = view.get('payments')
    services = view.get('services')
    if type(payments) is not list or type(services) is not list:
        return part(facts, negatives, witnesses, False, reasons + ['payment_or_service_channel_unread'])
    payment_records = {}
    for record in payments:
        evidence = checked(record, public, True)
        local_id = record.get('local_id')
        payer = record.get('payer')
        payee = record.get('payee')
        payer_text = record.get('payer_text')
        payee_text = record.get('payee_text')
        verb = record.get('transaction_verb')
        date = record.get('payment_date')
        if evidence is None or type(local_id) is not str or local_id in payment_records or not all(type(x) is str for x in (payer,payee,payer_text,payee_text,verb)):
            complete = False
            continue
        quote = ' '.join([row['quote'].lower() for row in evidence])
        if payer_text.lower() not in quote or payee_text.lower() not in quote or verb.lower() not in quote:
            complete = False
            add(reasons, 'payment_roles_not_source_explicit')
            continue
        if payer_text.lower() == payee_text.lower() and quote.count(payer_text.lower()) < 2:
            complete = False
            add(reasons, 'passive_income_recipient_is_not_both_payment_roles')
            continue
        if date is not None and (type(date) is not str or len(date) != 10 or date[4] != '-' or date[7] != '-'):
            complete = False
            add(reasons, 'payment_date_is_not_explicit_full_date')
            continue
        payment_records[local_id] = (record, evidence)
    service_ids = {}
    service_query_count = 0
    st = target_service(kernel)
    for index, record in enumerate(services):
        evidence = checked(record, public, True)
        local_id = record.get('local_id')
        worker = record.get('worker')
        employer = record.get('employer')
        worker_text = record.get('worker_text')
        employer_text = record.get('employer_text')
        basis = record.get('role_basis')
        linked = record.get('linked_payment_local_id')
        if evidence is None or type(local_id) is not str or local_id in service_ids or not all(type(x) is str for x in (worker,employer,worker_text,employer_text)) or basis not in ('explicit_service_roles','transaction_roles'):
            complete = False
            continue
        quote = ' '.join([row['quote'].lower() for row in evidence])
        if worker_text.lower() not in quote or employer_text.lower() not in quote:
            complete = False
            add(reasons, 'service_roles_not_source_explicit')
            continue
        if basis == 'transaction_roles':
            if type(linked) is not str or linked not in payment_records:
                complete = False
                add(reasons, 'transaction_service_missing_payment_link')
                continue
            payment_record = payment_records[linked][0]
            if payment_record.get('payer') != employer or payment_record.get('payee') != worker:
                complete = False
                add(reasons, 'transaction_service_roles_reversed')
                continue
        event = 'service_' + str(index)
        if record.get('is_query_service') is True:
            service_query_count += 1
            if type(st) is str:
                event = st
        service_ids[local_id] = event
        for row in evidence:
            add(witnesses, row)
        put(facts, 'service_', [event])
        put(facts, 'agent_', [event, worker])
        put(facts, 'patient_', [event, employer])
        if type(record.get('service_kind')) is str:
            put(facts, 'purpose_', [event, record.get('service_kind')])
        if type(record.get('service_venue')) is str:
            put(facts, 'location_', [event, record.get('service_venue')])
        if type(record.get('location')) is str:
            put(facts, 'location_', [event, record.get('location')])
            if type(record.get('country')) is str:
                put(facts, 'country_', [record.get('location'), record.get('country')])
        if type(record.get('start_date')) is str:
            put(facts, 'start_', [event, record.get('start_date')])
        if type(record.get('end_date')) is str:
            put(facts, 'end_', [event, record.get('end_date')])
    pt = target_payment(kernel)
    payment_query_count = 0
    for index, local_id in enumerate(payment_records):
        record, evidence = payment_records[local_id]
        payment = 'payment_' + str(index)
        if record.get('is_query_payment') is True:
            payment_query_count += 1
            if type(pt) is str:
                payment = pt
        linked = record.get('service_local_id')
        if linked is not None and linked not in service_ids:
            complete = False
            add(reasons, 'payment_links_unknown_service')
            continue
        for row in evidence:
            add(witnesses, row)
        put(facts, 'payment_', [payment])
        put(facts, 'agent_', [payment, record.get('payer')])
        put(facts, 'patient_', [payment, record.get('payee')])
        if type(record.get('amount')) in (int,float):
            put(facts, 'amount_', [payment, record.get('amount')])
        if type(record.get('medium')) is str:
            put(facts, 'means_', [payment, record.get('medium')])
        if type(record.get('payment_date')) is str:
            put(facts, 'start_', [payment, record.get('payment_date')])
        if type(linked) is str:
            put(facts, 'purpose_', [payment, service_ids[linked]])
    if type(st) is str and len(services) > 0 and service_query_count != 1:
        complete = False
        add(reasons, 'queried_service_role_not_uniquely_aligned')
    if type(pt) is str and len(payments) > 0 and payment_query_count != 1:
        complete = False
        add(reasons, 'queried_payment_role_not_uniquely_aligned')
    if not complete:
        add(reasons, component + '_one_or_more_records_unread_or_invalid')
    return part(facts, negatives, witnesses, complete, reasons)

