    complete = True
    if type(view) is not dict or view.get('extraction_status') != 'complete':
        return part([], [], [], False, [component + '_unread_or_ambiguous'])
    if not support(witnesses, view, public, False):
        complete = False
        add(reasons, component + '_complete_view_requires_current_witness')
    records = view.get('records')
    if type(records) is not list:
        return part(facts, negatives, witnesses, False, reasons + ['special_native_channel_unread'])
    simple = {'american_employer':'american_employer_','business':'business_','business_trust':'business_trust_','international_organization':'international_organization_','itemize_deductions':'itemize_deductions_','medical_institution':'medical_institution_','nurses_training_school':'nurses_training_school_','plan':'plan_'}
    states = {'citizenship':'citizenship_','disability':'disability_','migration':'migration_','nonresident_alien':'nonresident_alien_','retirement':'retirement_'}
    for index, record in enumerate(records):
        evidence = checked(record, public, True)
        kind = record.get('kind')
        subject = record.get('subject')
        marker = record.get('source_marker')
        subject_text = record.get('subject_text')
        if evidence is None or type(subject) is not str or type(marker) is not str or type(subject_text) is not str:
            complete = False
            continue
        quote = ' '.join([row['quote'].lower() for row in evidence])
        if marker.lower() not in quote or subject_text.lower() not in quote:
            complete = False
            add(reasons, 'special_native_roles_not_source_explicit')
            continue
        related = record.get('related')
        related_text = record.get('related_text')
        if related is not None and (type(related_text) is not str or related_text.lower() not in quote):
            complete = False
            add(reasons, 'special_native_related_role_not_witnessed')
            continue
        event = 'special_' + str(index)
        if kind in simple:
            put(facts, simple[kind], [event])
            put(facts, 'agent_', [event, subject])
            if type(record.get('category')) is str:
                put(facts, 'type_', [event, record.get('category')])
            if type(record.get('purpose')) is str:
                put(facts, 'purpose_', [event, record.get('purpose')])
            if kind == 'plan':
                for beneficiary in record.get('beneficiaries'):
                    put(facts, 'beneficiary_', [event, beneficiary])
        elif kind in states:
            put(facts, states[kind], [event])
            put(facts, 'agent_', [event, subject])
            if kind == 'citizenship' and type(related) is str:
                put(facts, 'patient_', [event, related])
            if kind == 'migration' and type(related) is str:
                put(facts, 'destination_', [event, related])
                if type(record.get('purpose')) is str:
                    put(facts, 'purpose_', [event, record.get('purpose')])
            if type(record.get('start_date')) is str:
                put(facts, 'start_', [event, record.get('start_date')])
            if type(record.get('end_date')) is str:
                put(facts, 'end_', [event, record.get('end_date')])
        elif kind == 'unemployment_compensation_agreement':
            if type(related) is not str:
                complete = False
                continue
            put(facts, 'unemployment_compensation_agreement_', [event])
            put(facts, 'agent_', [event, subject])
            put(facts, 'agent_', [event, related])
        elif kind == 'termination':
            worker = record.get('service_worker')
            employer = record.get('service_employer')
            condition_kind = record.get('condition_kind')
            condition_person = record.get('condition_person')
            if not all(type(x) is str for x in (worker,employer,condition_person)) or condition_kind not in ('disability','death') or employer != subject:
                complete = False
                add(reasons, 'termination_roles_incomplete')
                continue
            service = 'special_service_' + str(index)
            condition = 'special_condition_' + str(index)
            put(facts, 'service_', [service])
            put(facts, 'agent_', [service, worker])
            put(facts, 'patient_', [service, employer])
            if type(record.get('purpose')) is str:
                put(facts, 'purpose_', [service, record.get('purpose')])
            put(facts, condition_kind + '_', [condition])
            put(facts, 'agent_', [condition, condition_person])
            if type(record.get('condition_date')) is str:
                put(facts, 'start_', [condition, record.get('condition_date')])
            put(facts, 'termination_', [event])
            put(facts, 'agent_', [event, employer])
            put(facts, 'patient_', [event, service])
            put(facts, 'reason_', [event, condition])
            if type(record.get('start_date')) is str:
                put(facts, 'start_', [event, record.get('start_date')])
        else:
            complete = False
            continue
        for row in evidence:
            add(witnesses, row)
    if not complete:
        add(reasons, component + '_one_or_more_records_unread_or_invalid')
    return part(facts, negatives, witnesses, complete, reasons)

