                for beneficiary in record.get('beneficiaries'):
                    put(facts, 'beneficiary_', [event, beneficiary])
        elif kind in states:
            put(facts, states[kind], [event])
            put(facts, 'agent_', [event, subject])
            if kind == 'citizenship' and type(related) is str:
                put(facts, 'patient_', [event, related])
            if kind == 'migration' and type(related) is str:
                put(facts, 'destination_', [event, related])
                if type(record.get('purpose')) is str:
                    put(facts, 'purpose_', [event, record.get('purpose')])
            if type(record.get('start_date')) is str:
                put(facts, 'start_', [event, record.get('start_date')])
            if type(record.get('end_date')) is str:
                put(facts, 'end_', [event, record.get('end_date')])
        elif kind == 'unemployment_compensation_agreement':
            if type(related) is not str:
                complete = False
                continue
            put(facts, 'unemployment_compensation_agreement_', [event])
            put(facts, 'agent_', [event, subject])
            put(facts, 'agent_', [event, related])
        elif kind == 'termination':
            worker = record.get('service_worker')
            employer = record.get('service_employer')
            condition_kind = record.get('condition_kind')
            condition_person = record.get('condition_person')
            if not all(type(x) is str for x in (worker,employer,condition_person)) or condition_kind not in ('disability','death') or employer != subject:
                complete = False
                add(reasons, 'termination_roles_incomplete')
                continue
            service = 'special_service_' + str(index)
            condition = 'special_condition_' + str(index)
            put(facts, 'service_', [service])
            put(facts, 'agent_', [service, worker])
            put(facts, 'patient_', [service, employer])
            if type(record.get('purpose')) is str:
                put(facts, 'purpose_', [service, record.get('purpose')])
            put(facts, condition_kind + '_', [condition])
            put(facts, 'agent_', [condition, condition_person])
            if type(record.get('condition_date')) is str:
                put(facts, 'start_', [condition, record.get('condition_date')])
            put(facts, 'termination_', [event])
            put(facts, 'agent_', [event, employer])
            put(facts, 'patient_', [event, service])
            put(facts, 'reason_', [event, condition])
            if type(record.get('start_date')) is str:
                put(facts, 'start_', [event, record.get('start_date')])
        else:
            complete = False
            continue
        for row in evidence:
            add(witnesses, row)
    if not complete:
        add(reasons, component + '_one_or_more_records_unread_or_invalid')
    return part(facts, negatives, witnesses, complete, reasons)
